const requireChatParticipant = async (req, res, next) => {
  const roomId = String(req.params.roomId || '');
  if (mentorChannel(roomId) !== null) return canAccessMentorChannel(roomId,req.auth.role,req.method==='POST') ? next() : res.status(403).json({success:false,msg:'Bạn không có quyền truy cập hoặc đăng tin trong kênh Mentor này.'});
  if (roomId === 'homepage-live' || (!roomId.startsWith('mentor-chat-') && roomId.includes('::'))) return next();
  const deny = () => res.status(403).json({success:false,msg:'Bạn không có quyền truy cập cuộc trò chuyện này.'});
  if (roomId.startsWith('booking-chat-')) {
    const id = roomId.slice('booking-chat-'.length);
    if (!mongoose.isValidObjectId(id)) return deny();
    const booking = await Booking.findById(id);
    if (!booking || !isParticipant(booking, req.auth)) return deny();
    // Only include legacy history when it belongs unambiguously to this pair.
    const candidates = await Booking.find({mentorEmail:booking.mentorEmail,menteeName:booking.menteeName}).select('menteeEmail');
    req.chatRooms = [roomId];
    if (booking.menteeEmail && candidates.every(row => row.menteeEmail === booking.menteeEmail)) req.chatRooms.push(legacyRoom(booking));
    return next();
  }
  if (!roomId.startsWith('mentor-chat-')) return deny();
  // Compare complete room identifiers instead of splitting emails on hyphens.
  const candidates = await Booking.find(req.auth.role === 'admin' ? {} : {$or:[{mentorEmail:req.auth.email},{menteeEmail:req.auth.email}]}).select('mentorEmail menteeEmail menteeName');
  const booking = candidates.find(row => legacyRoom(row) === roomId);
  if (!booking || !booking.menteeEmail) return deny();
  const collisions = await Booking.find({mentorEmail:booking.mentorEmail,menteeName:booking.menteeName}).select('menteeEmail');
  if (!collisions.every(row => row.menteeEmail === booking.menteeEmail)) return deny();
  return next();
};
