const canSocketJoin = async (room, user) => {
  if (mentorChannel(room) !== null) return canAccessMentorChannel(room,user.role);
  if (room === 'homepage-live' || (!room.startsWith('mentor-chat-') && room.includes('::'))) return true;
  if (room.startsWith('booking-chat-')) {
    const id=room.slice('booking-chat-'.length);
    if(!mongoose.isValidObjectId(id))return false;
    const booking=await Booking.findById(id).select('mentorEmail menteeEmail');
    return !!booking&&isParticipant(booking,user);
  }
  if (!room.startsWith('mentor-chat-')) return false;
  const candidates=await Booking.find(user.role==='admin'?{}:{$or:[{mentorEmail:user.email},{menteeEmail:user.email}]}).select('mentorEmail menteeEmail menteeName');
  return candidates.some(row=>legacyRoom(row)===room&&row.menteeEmail);
};
io.on('connection',socket=>{socket.on('chat:join',async(roomId,ack)=>{const room=String(roomId||'');try{const allowed=await canSocketJoin(room,socket.user);if(allowed)await socket.join(room);if(typeof ack==='function')ack({ok:allowed});}catch{if(typeof ack==='function')ack({ok:false});}});});
