const payosRequest = async (path, options = {}) => {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 18000);
  try {
    const response = await fetch(`https://api-merchant.payos.vn${path}`, { ...options, signal:controller.signal, headers:{'Content-Type':'application/json','x-client-id':process.env.PAYOS_CLIENT_ID,'x-api-key':process.env.PAYOS_API_KEY,...(options.headers||{})} });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok || (payload.code && payload.code !== '00')) throw new Error(payload.desc || 'PayOS không thể xử lý yêu cầu thanh toán.');
    return payload.data;
  } catch (error) {
    if (error.name === 'AbortError') throw new Error('PayOS chưa phản hồi kịp. Nếu đã chuyển khoản, hãy kiểm tra trạng thái trước khi thử lại.');
    throw error;
  } finally { clearTimeout(timeout); }
};
