app.patch('/api/admin/payouts/:payoutCode',requireAuth,requireRole('admin'),async(req,res)=>{const status=String(req.body.status||'');const failureReason=String(req.body.failureReason||'').trim();const providerReference=String(req.body.providerReference||'').trim();if(!['SUCCESS','FAILED','CANCELLED'].includes(status))return res.status(400).json({success:false,msg:'Trạng thái payout không hợp lệ.'});if(status==='FAILED'&&!failureReason)return res.status(400).json({success:false,msg:'Cần nêu lý do payout thất bại.'});const payout=await Payout.findOneAndUpdate({payoutCode:req.params.payoutCode,status:'PROCESSING'},{$set:{status,failureReason:status==='FAILED'?failureReason:undefined,providerReference:status==='SUCCESS'?providerReference:undefined,completedAt:new Date()}},{new:true});if(!payout){const exists=await Payout.exists({payoutCode:req.params.payoutCode});return res.status(exists?409:404).json({success:false,msg:exists?'Payout đã được xử lý, không thể cập nhật lại.':'Không tìm thấy payout.'});}if(status==='FAILED'||status==='CANCELLED'){await User.findOneAndUpdate({email:payout.mentorEmail,role:'mentor'},{$inc:{availableXu:payout.amountXu}});await Transaction.updateOne({userEmail:payout.mentorEmail,type:'MENTOR_PAYOUT','metadata.payoutCode':payout.payoutCode},{$set:{status:'REFUNDED',metadata:{payoutCode:payout.payoutCode,reason:failureReason||'Yêu cầu rút đã bị hủy'}}});await Notification.create({userEmail:payout.mentorEmail,title:'Yêu cầu rút Xu không được duyệt',body:`Lệnh ${payout.payoutCode} đã ${status==='CANCELLED'?'bị hủy':'không thành công'}. ${payout.amountXu} Xu đã được hoàn về ví khả dụng.`,type:'WALLET'});}else{await Transaction.updateOne({userEmail:payout.mentorEmail,type:'MENTOR_PAYOUT','metadata.payoutCode':payout.payoutCode},{$set:{status:'SUCCESS'}});await Notification.create({userEmail:payout.mentorEmail,title:'Yêu cầu rút Xu đã được duyệt',body:`Lệnh ${payout.payoutCode} đã được PSIFU xác nhận chuyển khoản.`,type:'WALLET'});}await AuditLog.create({actorEmail:req.auth.email,action:'PAYOUT_STATUS_UPDATED',targetType:'Payout',targetId:payout.payoutCode,metadata:{status,failureReason,providerReference}});res.json({success:true,payout:toClient(payout)});});
