app.patch('/api/admin/support-tickets/:id',requireAuth,requireRole('admin'),async(req,res)=>{const status=String(req.body.status||'');if(!['OPEN','IN_PROGRESS','RESOLVED','CLOSED'].includes(status))return res.status(400).json({success:false,msg:'Trạng thái ticket không hợp lệ.'});const ticket=await SupportTicket.findByIdAndUpdate(req.params.id,{$set:{status}},{new:true});if(!ticket)return res.status(404).json({success:false,msg:'Không tìm thấy ticket.'});await AuditLog.create({actorEmail:req.auth.email,action:'SUPPORT_TICKET_STATUS_UPDATED',targetType:'SupportTicket',targetId:String(ticket._id),metadata:{status}});res.json({success:true,ticket:toClient(ticket)});});
