const guestTokenHash=token=>crypto.createHash('sha256').update(String(token||'')).digest('hex');
const guestConversation=async(req,res,next)=>{try{if(!mongoose.isValidObjectId(req.params.id))return res.status(404).json({success:false,msg:'Không tìm thấy hội thoại.'});const token=String(req.headers['x-support-token']||req.query.token||req.body?.token||'');if(!token)return res.status(401).json({success:false,msg:'Phiên hỗ trợ không hợp lệ.'});const conversation=await SupportConversation.findOne({_id:req.params.id,guestTokenHash:guestTokenHash(token)});if(!conversation)return res.status(401).json({success:false,msg:'Phiên hỗ trợ không hợp lệ hoặc đã hết hạn.'});req.supportConversation=conversation;next();}catch(error){next(error);}};
app.post('/api/guest-support/conversations',guestSupportLimiter,async(req,res)=>{const visitorName=String(req.body.visitorName||'').trim().slice(0,80),visitorEmail=cleanEmail(req.body.visitorEmail),message=String(req.body.message||'').trim(),aiTranscript=Array.isArray(req.body.aiTranscript)?req.body.aiTranscript.slice(-12):[];if(visitorName.length<2)return res.status(400).json({success:false,msg:'Vui lòng nhập tên để đội ngũ xưng hô với bạn.'});if(visitorEmail&&!emailPattern.test(visitorEmail))return res.status(400).json({success:false,msg:'Email không hợp lệ.'});if(!message||message.length>2000)return res.status(400).json({success:false,msg:'Nội dung cần từ 1 đến 2.000 ký tự.'});const token=crypto.randomBytes(24).toString('hex'),code=`WEB-${Date.now().toString(36).toUpperCase()}-${crypto.randomBytes(2).toString('hex').toUpperCase()}`;const conversation=await SupportConversation.create({code,guestTokenHash:guestTokenHash(token),visitorName,visitorEmail,status:'WAITING',lastMessageAt:new Date()});const context=aiTranscript.map(item=>`${item?.from==='user'?'Khách':'AI'}: ${String(item?.text||'').trim().slice(0,500)}`).filter(line=>!line.endsWith(': ')).join('\n');const docs=[];if(context)docs.push({conversationId:conversation._id,sender:'SYSTEM',senderName:'AI PSIFU',text:`Ngữ cảnh chuyển từ AI:\n${context}`});docs.push({conversationId:conversation._id,sender:'GUEST',senderName:visitorName,text:message});await SupportMessage.insertMany(docs);res.status(201).json({success:true,token,conversation:supportConversationClient(conversation),messages:(await SupportMessage.find({conversationId:conversation._id}).sort({createdAt:1})).map(toClient)});});
