app.post('/api/guest-support/conversations/:id/messages',guestSupportLimiter,guestConversation,async(req,res)=>{const message=String(req.body.text||'').trim();if(!message||message.length>2000)return res.status(400).json({success:false,msg:'Nội dung cần từ 1 đến 2.000 ký tự.'});if(req.supportConversation.status==='CLOSED')return res.status(409).json({success:false,msg:'Hội thoại đã đóng.'});const saved=await SupportMessage.create({conversationId:req.supportConversation._id,sender:'GUEST',senderName:req.supportConversation.visitorName,text:message});req.supportConversation.status=req.supportConversation.status==='RESOLVED'?'WAITING':req.supportConversation.status;req.supportConversation.lastMessageAt=new Date();req.supportConversation.unreadForAdmin=(req.supportConversation.unreadForAdmin||0)+1;await req.supportConversation.save();res.status(201).json({success:true,message:toClient(saved),conversation:supportConversationClient(req.supportConversation)});});
app.post('/api/users',authLimiter, async (req,res)=>{const email=cleanEmail(req.body.email),fullName=String(req.body.fullName||'').trim(),password=req.body.password,role=req.body.role||'mentee';if(!emailPattern.test(email))return res.status(400).json({success:false,msg:'Email không hợp lệ.'});if(fullName.length<2||fullName.length>80)return res.status(400).json({success:false,msg:'Họ tên phải từ 2 đến 80 ký tự.'});if(!validPassword(password))return res.status(400).json({success:false,msg:'Mật khẩu phải dài từ 8 đến 72 ký tự.'});if(!['mentee','mentor'].includes(role))return res.status(400).json({success:false,msg:'Vai trò đăng ký không hợp lệ.'});if(await User.exists({email}))return res.status(409).json({success:false,msg:'Email/Tài khoản này đã tồn tại!'});const user=await User.create({email,fullName,password:await bcrypt.hash(password,PASSWORD_HASH_ROUNDS),role,emailVerified:false,emailVerificationRequired:true,userXu:20,hasCheckedInToday:false,isFirstLogin:true});res.status(201).json({success:true,msg:'Đăng ký thành công! Hãy xác minh email.',user:toClient(user)});});
