app.post('/api/wallet/daily-check-in',requireAuth,async(req,res)=>{
  const session=await mongoose.startSession();let user;
  try {
    await session.withTransaction(async()=>{
      const today=new Date().toISOString().slice(0,10);
      user=await User.findOneAndUpdate({_id:req.auth.sub,lastCheckInDate:{$ne:today}},{$set:{lastCheckInDate:today,hasCheckedInToday:true},$inc:{userXu:1}},{new:true,session});
      if(!user)throw Object.assign(new Error('Bạn đã điểm danh hôm nay.'),{status:409});
      await Transaction.create([{userEmail:user.email,type:'DAILY_CHECK_IN',amount:1,status:'SUCCESS'}],{session});
    });
    res.json({success:true,userXu:user.userXu});
  } catch(error){if(error.status)return res.status(error.status).json({success:false,msg:error.message});throw error;}
  finally{await session.endSession();}
});
app.post('/api/auth/login', authLimiter, async (req, res) => {
  const email = req.body.email?.trim().toLowerCase();
  const user = await User.findOne({ email });
  if (!user) return res.status(404).json({ success: false, code: 'EMAIL_NOT_FOUND', msg: 'Email này chưa có tài khoản PSIFU.' });
  const passwordOk=await matchesPassword(req.body.password,user.password,bcrypt); const legacyPasswordOk=passwordOk&&!/^\$2[aby]\$/.test(user.password);
  if (!passwordOk&&!legacyPasswordOk) return res.status(401).json({ success: false, code: 'WRONG_PASSWORD', msg: 'Mật khẩu chưa chính xác. Vui lòng thử lại.' });
  if (user.emailVerificationRequired && !user.emailVerified) return res.status(403).json({ success:false, code:'EMAIL_NOT_VERIFIED', msg:'Hãy xác minh email trước khi đăng nhập.' });
  res.json({ success: true, user: toClient(user), accessToken:makeToken(user) });
  if(legacyPasswordOk||bcrypt.getRounds(user.password)>PASSWORD_HASH_ROUNDS){bcrypt.hash(req.body.password,PASSWORD_HASH_ROUNDS).then(password=>User.updateOne({_id:user._id,password:user.password},{$set:{password}})).catch(()=>{});}
});
app.post('/api/auth/google', authLimiter, async (req, res) => {
  const idToken = String(req.body.idToken || '');
  const clientId = process.env.GOOGLE_WEB_CLIENT_ID;
  if (!clientId) return res.status(503).json({ success: false, msg: 'Đăng nhập Google chưa được cấu hình trên máy chủ.' });
  if (!idToken || idToken.length > 4096) return res.status(400).json({ success: false, msg: 'Google ID token không hợp lệ.' });
  try {
    const response = await fetch(`https://oauth2.googleapis.com/tokeninfo?id_token=${encodeURIComponent(idToken)}`);
    const payload = await response.json().catch(() => ({}));
    if (!response.ok || payload.aud !== clientId || !['accounts.google.com', 'https://accounts.google.com'].includes(payload.iss) || !['true', true].includes(payload.email_verified) || !emailPattern.test(payload.email || '') || !payload.sub) {
      return res.status(401).json({ success: false, msg: 'Không thể xác minh tài khoản Google này.' });
    }
    const email = cleanEmail(payload.email);
    let user = await User.findOne({ $or: [{ googleSubject: payload.sub }, { email }] });
    if (user && user.googleSubject && user.googleSubject !== payload.sub) return res.status(409).json({ success: false, msg: 'Email này đã được liên kết với một tài khoản Google khác.' });
    if (!user) {
      const fullName = String(payload.name || email.split('@')[0]).trim().slice(0, 80) || 'PSIFU Member';
      user = await User.create({ fullName, email, password: await bcrypt.hash(crypto.randomBytes(32).toString('hex'), PASSWORD_HASH_ROUNDS), googleSubject: payload.sub, avatarUrl: payload.picture || '', emailVerified: true, role: 'mentee', isFirstLogin: true });
    } else {
      user.googleSubject = payload.sub;
      user.emailVerified = true;
      if (!user.avatarUrl && payload.picture) user.avatarUrl = payload.picture;
      await user.save();
    }
    res.json({ success: true, user: toClient(user), accessToken: makeToken(user) });
  } catch (error) {
    console.error('Google sign-in verification:', error.message);
    res.status(502).json({ success: false, msg: 'Không thể xác minh Google lúc này. Vui lòng thử lại.' });
  }
});
app.patch('/api/users/:email',requireAuth,requireSelfOrAdmin(), async (req,res)=>{const allowed=['fullName','avatarUrl','university','academicYear','fptK','studentId','major','specialization','track','currentTerm','mentorBio','mentorCourses','mentorAvailability','notificationPreferences','isFirstLogin'];const updates={};for(const key of allowed)if(req.body[key]!==undefined)updates[key]=req.body[key];if(updates.fullName!==undefined&&(String(updates.fullName).trim().length<2||String(updates.fullName).trim().length>80))return res.status(400).json({success:false,msg:'Họ tên phải từ 2 đến 80 ký tự.'});const user=await User.findOneAndUpdate({email:req.params.email.toLowerCase()},{$set:updates},{new:true});if(!user)return res.status(404).json({success:false});res.json({success:true,user:toClient(user)});});
