app.get('/api/mentors/:email/availability',requireAuth,async(req,res)=>{const mentorEmail=cleanEmail(req.params.email);const date=String(req.query.date||'');if(!/^\d{4}-\d{2}-\d{2}$/.test(date))return res.status(400).json({success:false,msg:'Ngày phải theo định dạng YYYY-MM-DD.'});const mentor=await User.findOne({email:mentorEmail,role:'mentor'}).select('mentorAvailability');if(!mentor)return res.status(404).json({success:false,msg:'Không tìm thấy Mentor.'});const occupied=await Booking.find({mentorEmail,dateTime:{$regex:`^${date.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')} `},status:{$ne:'Đã hủy'}}).select('dateTime');const day=['Chủ Nhật','Thứ Hai','Thứ Ba','Thứ Tư','Thứ Năm','Thứ Sáu','Thứ Bảy'][new Date(`${date}T00:00:00`).getDay()];const ranges=mentor.mentorAvailability?.accepting===false?[]:(mentor.mentorAvailability?.slots?.find(slot=>slot.day===day)?.ranges||[]);res.json({success:true,date,accepting:mentor.mentorAvailability?.accepting!==false,ranges,occupiedTimes:occupied.map(item=>String(item.dateTime).split(' ')[1]).filter(Boolean)});});
app.post('/api/bookings', requireAuth, async (req,res) => {
  if (req.auth.role !== 'mentee') return res.status(403).json({success:false,msg:'Chỉ Mentee có thể đặt lịch.'});
  const mentorEmail=cleanEmail(req.body.mentorEmail), dateTime=String(req.body.dateTime||'');
  const matched=dateTime.match(/^(\d{4}-\d{2}-\d{2})\s+(\d{2}:\d{2})$/);
  const fail=(status,msg)=>{throw Object.assign(new Error(msg),{status});};
  if (!matched || !Number.isFinite(Date.parse(matched[1]+'T'+matched[2]+':00+07:00')) || Date.parse(matched[1]+'T'+matched[2]+':00+07:00') <= Date.now()) return res.status(400).json({success:false,msg:'Vui lòng chọn thời gian hợp lệ trong tương lai.'});
  const session=await mongoose.startSession();
  let result;
  try {
    await session.withTransaction(async () => {
      // Updating the mentor serializes slot reservations across app/server instances.
      const mentor=await User.findOneAndUpdate({email:mentorEmail,role:'mentor'},{$inc:{bookingRevision:1}},{new:true,session});
      const mentee=await User.findById(req.auth.sub).session(session);
      if (!mentor || !mentee) fail(404,'Không tìm thấy tài khoản.');
      const day=['Chủ Nhật','Thứ Hai','Thứ Ba','Thứ Tư','Thứ Năm','Thứ Sáu','Thứ Bảy'][new Date(matched[1]+'T00:00:00Z').getUTCDay()];
      const minute=value=>{const parts=value.split(':').map(Number);return parts[0]*60+parts[1];};
      const start=minute(matched[2]);
      const ranges=mentor.mentorAvailability?.slots?.find(slot=>slot.day===day)?.ranges||[];
      if (mentor.mentorAvailability?.accepting===false || !ranges.some(range=>{const [from,to]=String(range).split('-').map(value=>value.trim());return from&&to&&start>=minute(from)&&start+60<=minute(to);})) fail(409,'Mentor không mở đủ 60 phút ở khung giờ này.');
      const occupied=await Booking.find({mentorEmail,dateTime:{$regex:'^'+matched[1]+' '},status:{$ne:STATUS.cancelled}}).session(session);
      if (occupied.some(row=>Math.abs(minute(row.dateTime.split(' ')[1])-start)<60)) fail(409,'Khung giờ này đã có người đặt. Vui lòng chọn giờ khác.');
      const fee=Number(mentor.mentorFee ?? 50);
      if (!Number.isFinite(fee)||fee<0) fail(400,'Phí mentoring không hợp lệ.');
      const charged=await User.findOneAndUpdate({_id:mentee._id,userXu:{$gte:fee}},{$inc:{userXu:-fee,escrowXu:fee}},{new:true,session});
      if (!charged) fail(400,'Bạn không đủ Xu để đặt lịch.');
      const [booking]=await Booking.create([{mentorEmail,mentorName:mentor.fullName,menteeName:mentee.fullName,menteeEmail:req.auth.email,course:String(req.body.course||'').slice(0,80),dateTime,note:String(req.body.note||'').trim().slice(0,2000),fee}],{session});
      await Transaction.create([{userEmail:req.auth.email,type:'BOOKING_ESCROW',amount:-fee,status:'HELD',metadata:{bookingId:String(booking._id),mentorEmail}}],{session});
      result={success:true,booking:toClient(booking),userXu:charged.userXu};
    });
    res.status(201).json(result);
  } catch(error) { if(error.status)return res.status(error.status).json({success:false,msg:error.message}); throw error; }
  finally { await session.endSession(); }
});
app.patch('/api/bookings/:id', requireAuth, async (req,res) => {
  if (!mongoose.isValidObjectId(req.params.id)) return res.status(404).json({success:false});
  const session=await mongoose.startSession();
  const fail=(status,msg)=>{throw Object.assign(new Error(msg),{status});};
  try {
    await session.withTransaction(async () => {
      const booking=await Booking.findById(req.params.id).session(session);
      if (!booking || !isParticipant(booking,req.auth)) fail(404,'Không tìm thấy lịch hẹn.');
      if (booking.status === req.body.status) return; // Idempotent response: no wallet changes.
      if (!canTransition(booking.status,req.body.status,req.auth.role)) fail(409,'Không thể chuyển trạng thái lịch hẹn này.');
      const previous=booking.status;
      booking.status=req.body.status;
      await booking.save({session});
      if (booking.fee>0 && [STATUS.cancelled,STATUS.completed].includes(booking.status)) {
        const refund=booking.status===STATUS.cancelled;
        const mentee=await User.findOneAndUpdate({email:booking.menteeEmail,escrowXu:{$gte:booking.fee}},{$inc:{escrowXu:-booking.fee,...(refund?{userXu:booking.fee}:{})}},{session,new:true});
        if (!mentee) fail(409,'Số dư ký quỹ không khớp. Vui lòng liên hệ hỗ trợ.');
        if (!refund) {
          const mentor=await User.findOneAndUpdate({email:booking.mentorEmail},{$inc:{availableXu:booking.fee}},{session,new:true});
          if (!mentor) fail(409,'Không tìm thấy ví Mentor.');
        }
        await Transaction.create([{userEmail:refund?booking.menteeEmail:booking.mentorEmail,type:refund?'BOOKING_REFUND':'BOOKING_RELEASE',amount:booking.fee,status:'SUCCESS',metadata:{bookingId:String(booking._id),previousStatus:previous}}],{session});
      }
    });
    res.json({success:true});
  } catch(error) { if(error.status)return res.status(error.status).json({success:false,msg:error.message}); throw error; }
  finally { await session.endSession(); }
});
app.post('/api/bookings/:id/rating',requireAuth,async(req,res)=>{const booking=await Booking.findOne({_id:req.params.id,menteeEmail:req.auth.email});const score=Number(req.body.score);const comment=String(req.body.comment||'').trim();if(!booking)return res.status(404).json({success:false,msg:'Không tìm thấy lịch hẹn.'});if(booking.status!=='Đã hoàn thành')return res.status(409).json({success:false,msg:'Chỉ đánh giá sau khi buổi học hoàn thành.'});if(booking.rating?.score)return res.status(409).json({success:false,msg:'Buổi học này đã được đánh giá.'});if(!Number.isInteger(score)||score<1||score>5)return res.status(400).json({success:false,msg:'Vui lòng chọn từ 1 đến 5 sao.'});booking.rating={score,comment:comment.slice(0,1000),createdAt:new Date()};await booking.save();res.status(201).json({success:true,rating:booking.rating});});
