app.patch('/api/mentor-documents/:id/activity',requireAuth,async(req,res)=>{
  if(!mongoose.isValidObjectId(req.params.id))return res.status(404).json({success:false,msg:'Không tìm thấy tài liệu.'});
  const document=await MentorDocument.findOne({_id:req.params.id,status:'PUBLISHED'});
  if(!document)return res.status(404).json({success:false,msg:'Tài liệu không còn được xuất bản.'});
  const canRead=document.mentorEmail===req.auth.email || Number(document.fee||0)===0 || !!await DocumentUnlock.exists({userEmail:req.auth.email,documentId:document._id});
  let patch;
  try{patch=activityUpdate(req.body,canRead)}catch(error){return res.status(error.status||400).json({success:false,msg:error.message});}
  const filter={userEmail:req.auth.email,documentId:document._id};
  let activity;
  try{activity=await DocumentActivity.findOneAndUpdate(filter,{$set:patch},{new:true,upsert:true,runValidators:true});}
  catch(error){if(error.code!==11000)throw error;activity=await DocumentActivity.findOneAndUpdate(filter,{$set:patch},{new:true,runValidators:true});}
  res.json({success:true,activity:toClient(activity)});
});
