app.post('/api/mentor-documents/:id/unlock',requireAuth,async(req,res)=>{const email=req.auth.email;if(cleanEmail(req.body.email)!==email)return res.status(403).json({success:false,msg:'Bạn chỉ được mở khóa cho chính mình.'});const document=await MentorDocument.findOne({_id:req.params.id,status:'PUBLISHED'});if(!document)return res.status(404).json({success:false,msg:'Không tìm thấy tài liệu đã xuất bản.'});const exists=await DocumentUnlock.exists({userEmail:email,documentId:document._id});if(exists)return res.json({success:true,alreadyUnlocked:true,userXu:(await User.findOne({email}).select('userXu'))?.userXu});const fee=Number(document.fee||0);const user=await User.findOneAndUpdate({email,userXu:{$gte:fee}},{$inc:{userXu:-fee}},{new:true});if(!user)return res.status(400).json({success:false,msg:'Bạn không đủ Xu để mở khóa tài liệu.'});try{await DocumentUnlock.create({userEmail:email,documentId:document._id});await MentorDocument.findByIdAndUpdate(document._id,{$inc:{unlocks:1,revenue:fee}});await Transaction.create({userEmail:email,type:'DOCUMENT_UNLOCK',amount:-fee,status:'SUCCESS',metadata:{documentId:String(document._id),title:document.title}});await AuditLog.create({actorEmail:email,action:'DOCUMENT_UNLOCKED',targetType:'MentorDocument',targetId:String(document._id),metadata:{fee,title:document.title}});res.status(201).json({success:true,userXu:user.userXu});}catch(error){await User.findOneAndUpdate({email},{$inc:{userXu:fee}});if(error?.code===11000)return res.json({success:true,alreadyUnlocked:true,userXu:(await User.findOne({email}).select('userXu'))?.userXu});throw error;}});
